<script setup lang="ts">
import { Activity, ChevronRight, Clock3, Eye, RefreshCw, Search, ShieldAlert, Trash2, X } from 'lucide-vue-next'
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { ApiRequestError, deletePublicRun, getPublicRun, getPublicRunStats, listPublicRuns } from '@/api/client'
import type { PublicRunDetail, PublicRunStats, PublicRunStatus, PublicRunSummary } from '@/types'

const items=ref<PublicRunSummary[]>([]),stats=ref<PublicRunStats|null>(null),detail=ref<PublicRunDetail|null>(null)
const selectedId=ref(''),status=ref(''),appId=ref(''),query=ref(''),nextCursor=ref<string|null>(null)
const loading=ref(false),detailLoading=ref(false),error=ref(''),pollError=ref(''),message=ref('')
const tab=ref<'conversation'|'events'>('conversation'),sensitive=ref(false)
let listVersion=0,detailVersion=0,timer:number|undefined

const statusText:Record<string,string>={active:'可交互',running:'运行中',completed:'已完成',failed:'失败',expired:'已过期',interrupted:'已中断'}
const birthLabels:Record<string,string>={name:'姓名',gender:'性别',birth_date:'出生日期',birth_time:'出生时间',birth_time_unknown:'时辰未知',province_code:'省份代码',city_code:'城市代码',true_solar_time:'真太阳时',focus_topics:'关注方向'}
const dreamLabels:Record<string,string>={emotions:'情绪',recurring:'重复梦',dream_length:'梦境字数',has_recent_context:'近期背景'}
const failures=computed(()=>stats.value?(stats.value.total.reports_failed+stats.value.total.questions_failed):0)
const apps=computed(()=>Array.from(new Map(items.value.map(item=>[item.app_id,item.app_name])).entries()))
const detailKind=computed(()=>detail.value?.input.kind||'fortune')
const inputFields=computed(()=>detail.value?.input.fields||{})
const fieldLabels=computed(()=>detailKind.value==='dream'?dreamLabels:birthLabels)
const contextSummary=computed(()=>detail.value?.context.summary||{})
const pillars=computed(()=>Object.entries((contextSummary.value.pillars||{}) as Record<string,{gan_zhi:string}>))
const dreamSymbols=computed(()=>(contextSummary.value.symbols||[]) as Array<{id:string;label:string}>)
function format(value:string){return value?new Date(value).toLocaleString('zh-CN'):'—'}
function duration(value:number){return value<1000?`${value} ms`:`${(value/1000).toFixed(1)} s`}
function errorCode(reason:unknown){return reason instanceof ApiRequestError?reason.code:''}

function listQuery(cursor?:string){return {app_id:appId.value||undefined,status:(status.value||undefined) as PublicRunStatus|undefined,query:query.value.trim()||undefined,limit:50,cursor}}
async function load(manual=false){const version=++listVersion;if(manual){loading.value=true;error.value=''}try{const [page,total]=await Promise.all([listPublicRuns(listQuery()),getPublicRunStats()]);if(version!==listVersion)return;items.value=page.items;nextCursor.value=page.next_cursor;stats.value=total;pollError.value=''}catch(reason){if(version!==listVersion)return;(manual?error:pollError).value=(reason as Error).message}finally{if(version===listVersion)loading.value=false}}
async function loadMore(){if(!nextCursor.value)return;const version=++listVersion;loading.value=true;try{const page=await listPublicRuns(listQuery(nextCursor.value));if(version!==listVersion)return;items.value=[...items.value,...page.items];nextCursor.value=page.next_cursor}catch(reason){error.value=(reason as Error).message}finally{if(version===listVersion)loading.value=false}}
async function loadDetail(id=selectedId.value,includeSensitive=sensitive.value){const version=++detailVersion;if(!id)return;detailLoading.value=true;try{const result=await getPublicRun(id,includeSensitive);if(version!==detailVersion||id!==selectedId.value)return;detail.value=result}catch(reason){if(version!==detailVersion)return;const code=errorCode(reason);if(code==='PUBLIC_SESSION_NOT_FOUND'){message.value='会话已过期或已删除';closeDrawer();await load()}else error.value=(reason as Error).message}finally{if(version===detailVersion)detailLoading.value=false}}
function inspect(item:PublicRunSummary){selectedId.value=item.session_id;sensitive.value=false;tab.value='conversation';detail.value=null;loadDetail(item.session_id,false)}
function closeDrawer(){detailVersion++;selectedId.value='';detail.value=null;sensitive.value=false;tab.value='conversation'}
async function reveal(){sensitive.value=true;await loadDetail(selectedId.value,true)}
async function remove(){if(!selectedId.value||!confirm('确定删除这条匿名会话吗？此操作不可恢复，且不会返还已消耗额度。'))return;try{await deletePublicRun(selectedId.value);message.value='匿名会话已删除';closeDrawer();await load(true)}catch(reason){const code=errorCode(reason);if(code==='SESSION_RUNNING')error.value='当前运行结束后才能删除会话';else if(code==='PUBLIC_SESSION_NOT_FOUND'){message.value='会话已过期或已删除';closeDrawer();await load()}else error.value=(reason as Error).message}}
async function poll(){await load(false);if(selectedId.value)await loadDetail()}
async function manualRefresh(){await load(true);if(selectedId.value)await loadDetail()}
function onKeydown(event:KeyboardEvent){if(event.key==='Escape'&&selectedId.value)closeDrawer()}
let searchTimer:number|undefined
watch([status,appId],()=>load(true))
watch(query,()=>{window.clearTimeout(searchTimer);searchTimer=window.setTimeout(()=>load(true),250)})
onMounted(()=>{load(true);timer=window.setInterval(poll,15000);window.addEventListener('keydown',onKeydown)})
onBeforeUnmount(()=>{window.clearInterval(timer);window.clearTimeout(searchTimer);window.removeEventListener('keydown',onKeydown);listVersion++;detailVersion++})
</script>

<template>
  <div class="page-heading public-runs-heading"><div><div class="eyebrow">PUBLIC OPERATIONS</div><h1>公开运行</h1><p class="subtitle">匿名发布应用的会话、运行状态与累计指标。</p></div><button class="icon-button" title="刷新" :disabled="loading" @click="manualRefresh"><RefreshCw :size="16" :class="{spin:loading}"/></button></div>
  <div v-if="message" class="notice">{{message}}</div><div v-if="error" class="error">{{error}}</div><div v-if="pollError" class="public-poll-error">自动刷新失败 · {{pollError}}</div>
  <section class="stats public-stats" aria-label="累计统计"><div class="stat"><div class="stat-value">{{stats?.total.sessions_created??'—'}}</div><div class="stat-label">累计匿名会话</div></div><div class="stat"><div class="stat-value">{{stats?.total.runs_completed??'—'}}</div><div class="stat-label">成功运行</div></div><div class="stat"><div class="stat-value">{{stats?failures:'—'}}</div><div class="stat-label">失败运行</div></div><div class="stat"><div class="stat-value">{{stats?duration(stats.total.average_duration_ms):'—'}}</div><div class="stat-label">平均耗时</div></div></section>
  <div class="public-toolbar"><label><span>应用</span><select v-model="appId"><option value="">全部应用</option><option v-for="app in apps" :key="app[0]" :value="app[0]">{{app[1]}}</option></select></label><label><span>状态</span><select v-model="status"><option value="">全部状态</option><option v-for="value in ['active','running','completed','failed','expired']" :key="value" :value="value">{{statusText[value]}}</option></select></label><label class="public-search"><Search :size="14"/><input v-model="query" aria-label="搜索会话 ID" placeholder="搜索会话 ID"/></label></div>
  <div v-if="items.length" class="table-wrap"><table class="data-table public-runs-table"><thead><tr><th>会话</th><th>应用</th><th>状态</th><th>消息 / 运行</th><th>剩余追问</th><th>最近活动</th><th></th></tr></thead><tbody><tr v-for="item in items" :key="item.session_id" :class="{selected:item.session_id===selectedId}" @click="inspect(item)"><td><div class="primary-cell mono-id">{{item.session_id}}</div><div class="cell-sub">创建 {{format(item.created_at)}}</div></td><td>{{item.app_name}}</td><td><span class="badge" :class="item.status==='failed'?'badge--bad':item.status==='running'?'badge--warn':item.status==='completed'?'badge--ok':''">{{statusText[item.status]}}</span></td><td>{{item.message_count}} / {{item.run_count}}</td><td>{{item.remaining_questions}}</td><td>{{format(item.updated_at)}}</td><td><ChevronRight :size="15"/></td></tr></tbody></table></div>
  <div v-else-if="loading" class="public-inline-empty">正在加载公开会话...</div><div v-else class="empty"><div><Activity/><h2>暂无公开会话</h2><p>新的匿名会话会自动显示在这里。</p></div></div><div class="public-more" v-if="nextCursor"><button class="button button--secondary" :disabled="loading" @click="loadMore">加载更多</button></div>
  <div v-if="selectedId" class="public-drawer-backdrop" @click="closeDrawer"/><aside v-if="selectedId" class="public-drawer" role="dialog" aria-modal="true" aria-label="公开会话详情"><header><div><div class="eyebrow">ANONYMOUS SESSION</div><h2>{{selectedId}}</h2></div><button class="icon-button" title="关闭" @click="closeDrawer"><X :size="17"/></button></header><div v-if="detailLoading&&!detail" class="public-drawer-loading">加载中...</div><template v-if="detail"><div class="public-drawer-meta"><span class="badge">{{statusText[detail.session.status]}}</span><b>{{detail.session.app_name}}</b><span>剩余 {{detail.session.remaining_questions}} 次</span></div><dl class="public-time-grid"><div><dt>创建</dt><dd>{{format(detail.session.created_at)}}</dd></div><div><dt>过期</dt><dd>{{format(detail.session.expires_at)}}</dd></div></dl><section class="public-birth"><div class="public-section-title"><h3>{{detailKind==='dream'?'梦境摘要':'出生资料'}}</h3><button v-if="detailKind==='fortune'&&!sensitive" class="button button--secondary" @click="reveal"><Eye :size="14"/>显示敏感资料</button></div><dl><div v-for="(value,key) in inputFields" :key="key"><dt>{{fieldLabels[String(key)]||key}}</dt><dd>{{Array.isArray(value)?value.join('、'):typeof value==='boolean'?(value?'是':'否'):value??'—'}}</dd></div></dl><div v-if="detailKind==='fortune'" class="public-pillars"><span v-for="pillar in pillars" :key="pillar[0]"><small>{{pillar[0]}}</small><b>{{pillar[1].gan_zhi}}</b></span></div><div v-else class="public-pillars"><span v-for="symbol in dreamSymbols" :key="symbol.id"><b>{{symbol.label}}</b></span></div></section><div class="tabs public-tabs"><button class="tab" :class="{active:tab==='conversation'}" @click="tab='conversation'">对话 {{detail.messages.length}}</button><button class="tab" :class="{active:tab==='events'}" @click="tab='events'">运行事件 {{detail.events.length}}</button></div><section v-if="tab==='conversation'" class="public-conversation"><article v-for="item in detail.messages" :key="item.id" :class="item.role"><small>{{item.role==='user'?'访客':'智能体'}}</small><p>{{item.content}}</p></article><div v-if="!detail.messages.length" class="public-inline-empty">暂无对话</div></section><section v-else class="public-events"><div v-if="detail.historical_events_unavailable" class="notice"><ShieldAlert :size="15"/>历史记录未采集事件</div><article v-for="run in detail.runs" :key="run.run_id"><header><b>{{run.run_id.slice(0,12)}}</b><span class="badge">{{statusText[run.status]||run.status}}</span></header><div v-for="event in run.events" :key="`${run.run_id}-${event.sequence}`" class="public-event"><span>{{event.sequence}}</span><div><b>{{event.type}}</b><small><Clock3 :size="11"/>{{duration(event.duration_ms)}} · {{format(event.timestamp)}}</small><code v-if="event.error_code">{{event.error_code}}</code></div></div></article><div v-if="!detail.runs.length&&!detail.historical_events_unavailable" class="public-inline-empty">暂无运行事件</div></section><footer><button class="button button--danger" :disabled="detail.session.status==='running'" @click="remove"><Trash2 :size="14"/>删除这条匿名会话</button><p>不可恢复，且不会返还已消耗额度。</p></footer></template></aside>
</template>
